-- 100 sample food and drink items for the NutriLife catalog.
-- Import this file in phpMyAdmin after selecting the `nutrilife` database.
-- 50 food and 50 drink items. Stable IDs and duplicate-key updates make this seed safe to import again.

SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`),
  `nameNormalized` = VALUES(`nameNormalized`),
  `brand` = VALUES(`brand`),
  `kind` = VALUES(`kind`),
  `calories` = VALUES(`calories`),
  `protein` = VALUES(`protein`),
  `carbs` = VALUES(`carbs`),
  `fat` = VALUES(`fat`),
  `fiber` = VALUES(`fiber`),
  `sugar` = VALUES(`sugar`),
  `sodium` = VALUES(`sodium`),
  `source` = VALUES(`source`);
